module TopModule (
    input  logic clk,
    input  logic a,
    input  logic b,
    output logic q,
    output logic state
);

  // Combinational logic for output q and next-state
  always_comb begin
    if (state) begin
      q = (a == b);
    end else begin
      q = ~a & b;
    end
  end

  // Sequential logic for the 1-bit state memory
  always_ff @(posedge clk) begin
    if (state) begin
      state <= ~(a ^ b);
    end else begin
      state <= ~a & b;
    end
  end

endmodule

